INSERT INTO message (description, date, importance, personne_id, categorie_id) VALUES
  ('Un peu confuse au réveil, elle a demandé plusieurs fois quel jour on était. Rassurée grâce au calendrier.', '2025-11-01', 'moyenne', 10, 4),
  ('Belle après-midi avec Maman : albums photos, gâteau et beaucoup de rires.', '2025-11-03', 'faible', 3, 4),
  ('Passage assis-debout de plus en plus fluide, bravo à elle !', '2025-11-03', 'faible', 9, 5),
  ('Légère rougeur au talon, crème appliquée. À surveiller aux prochains passages.', '2025-11-04', 'faible', 10, 1),
  ('Bonne participation : elle a reconnu les photos de famille et raconté plusieurs souvenirs.', '2025-11-04', 'faible', 12, 4),
  ('Prise de sang faite ce matin, Maman a bien supporté. Résultats à récupérer sous 48 h au laboratoire.', '2025-11-05', 'moyenne', 2, 1),
  ('Tension et pouls corrects ce matin, rien de particulier à signaler.', '2025-11-05', 'faible', 8, 1),
  ('Plus de produits d''entretien, à ajouter à la liste : lessive et savon.', '2025-11-05', 'faible', 13, 6),
  ('Courrier de la caisse de retraite reçu, je m''en occupe ce week-end.', '2025-11-06', 'faible', 2, 7),
  ('Elle monte les marches du perron avec appui sur la rampe. Exercices à poursuivre entre les séances.', '2025-11-06', 'faible', 9, 5),
  ('Elle s''est habillée presque seule, avec de l''aide uniquement pour les boutons.', '2025-11-06', 'faible', 10, 5),
  ('Un peu confuse au réveil, elle a demandé plusieurs fois quel jour on était. Rassurée grâce au calendrier.', '2025-11-08', 'moyenne', 10, 4),
  ('Résultats présentés : pas de modification majeure. On maintient le traitement et on réévalue dans 3 mois.', '2025-11-10', 'moyenne', 7, 1),
  ('Tension un peu haute, à recontrôler au prochain passage. Je préviens le Dr Vasseur si ça persiste.', '2025-11-10', 'moyenne', 8, 1),
  ('Séance agréable, elle a raconté ses souvenirs de vacances à Biarritz pendant les exercices.', '2025-11-10', 'faible', 9, 4),
  ('Elle s''est habillée presque seule, avec de l''aide uniquement pour les boutons.', '2025-11-11', 'faible', 10, 5),
  ('Moment agréable : on a feuilleté un album photos en préparant le repas.', '2025-11-12', 'faible', 13, 4),
  ('Douleur au genou en fin de séance : glace et exercices allégés. À signaler au médecin si ça persiste.', '2025-11-13', 'moyenne', 9, 1),
  ('Petit-déjeuner pris avant mon passage, elle avait bon appétit et a bien bu.', '2025-11-14', 'faible', 8, 3),
  ('Toilette faite sans difficulté, elle a participé à chaque étape.', '2025-11-15', 'faible', 10, 5),
  ('Oubli d''une prise constaté sur le pilulier. Rappel fait à Marguerite, merci de vérifier le pilulier chaque soir.', '2025-11-17', 'moyenne', 8, 2),
  ('Séance du jour : bonne énergie, marche sur 50 m avec le déambulateur.', '2025-11-17', 'faible', 9, 5),
  ('Visite à domicile : état général correct, poids stable. Tension à suivre chaque semaine par l''infirmier.', '2025-11-18', 'moyenne', 6, 1),
  ('Elle a refusé de se laver les cheveux aujourd''hui, on reprend à la prochaine toilette.', '2025-11-18', 'moyenne', 10, 5),
  ('Séance agréable : elle a chanté pendant l''exercice de mémoire musicale.', '2025-11-18', 'faible', 12, 4),
  ('Je serai là dimanche, je viens avec le gâteau préféré de Maman.', '2025-11-19', 'faible', 3, 6),
  ('Poids stable, peau en bon état. Elle a bien dormi selon ses dires.', '2025-11-19', 'faible', 8, 1),
  ('Séance du jour : bonne énergie, marche sur 50 m avec le déambulateur.', '2025-11-20', 'faible', 9, 5),
  ('Légère rougeur au talon, crème appliquée. À surveiller aux prochains passages.', '2025-11-20', 'faible', 10, 1),
  ('Stock de compresses et de pansements bientôt épuisé, à racheter.', '2025-11-21', 'faible', 8, 2),
  ('Mauvaise nuit selon Marguerite, un peu fatiguée mais coopérante.', '2025-11-22', 'moyenne', 10, 4),
  ('Mutuelle contactée : le remboursement des séances de kiné est confirmé.', '2025-11-24', 'moyenne', 2, 7),
  ('Légère fatigue ce matin, pas de fièvre. Je surveille et je repasse comme prévu.', '2025-11-24', 'moyenne', 8, 1),
  ('Passage assis-debout de plus en plus fluide, bravo à elle !', '2025-11-24', 'faible', 9, 5),
  ('Elle a refusé de se laver les cheveux aujourd''hui, on reprend à la prochaine toilette.', '2025-11-25', 'moyenne', 10, 5),
