-- seed.sql : jeu de données cohérent pour Vi'Assist (à lancer APRÈS 001, 002, 003 et 004)
--
-- Histoire : Marguerite Delacroix (bénéficiaire, 85 ans) vit chez elle. Sa fille Sophie
-- (admin, aidante principale), son fils Laurent, sa petite-fille Camille et sa voisine
-- Odile l'entourent. Des intervenants se relaient : médecin traitant, neurologue,
-- infirmier, kinésithérapeute, orthophoniste, aide-soignante et auxiliaire de vie.
-- Martine Perrin, ancienne auxiliaire de vie (jusqu'en 2025), est archivée (est_archive = TRUE) :
-- Karine Dupuis la remplace à partir du 1er janvier 2026.
--
-- Dates FIXES (pas de CURRENT_DATE) :
--   * événements : du 01/11/2025 au 31/12/2027, une cinquantaine par mois, 3 par jour maximum
--   * messages   : du 01/11/2025 au 10/11/2026 (le journal ne contient pas de messages dans le futur)
--
-- Ce script ne contient que des INSERT. Les id des événements ne sont pas écrits : ils valent 1, 2, 3…
-- dans l'ordre d'insertion (donc dans l'ordre chronologique), et la table participer s'y réfère.
-- Les valeurs numériques « de référence » viennent de la migration 003 (ordre de création) :
--   role_id           : 1 admin, 2 invité, 3 proche, 4 intervenant, 5 bénéficiaire
--   type_evenement_id : 1 Médical, 2 Paramédical, 3 Aide à domicile, 4 Autres, 5 Proches
--   categorie_id      : 1 Santé, 2 Traitement, 3 Alimentation, 4 Humeur et comportement,
--                       5 Autonomie et hygiène, 6 Logistique, 7 Administratif
--
-- Tous les comptes ont le même mot de passe : Motdepasse1!
-- ATTENTION : ce script vide d'abord personne, evenement, participer, message et categorie.

BEGIN;

TRUNCATE participer, message, evenement, categorie, personne RESTART IDENTITY CASCADE;

